/**
 * The price line of a product page: the price (integer minor units in the currency), the old price (compare_at)
 * struck through when higher, and the badge.
 */
import { type ReactNode } from "react";
import { Badge, Group, Inline, Text } from "../compose";
import { fmtMoney } from "../utils";

export type ProductPriceProps = {
  price: number;
  compareAt?: number;
  currency: string;
  badge?: string;
  was: string;
};

export function ProductPrice({ price, compareAt, currency, badge = "", was }: ProductPriceProps) {
  return (
    <Group gap="4" align="center" className="flex-wrap">
      <Text size="4xl" weight="bold">
        {fmtMoney(price, currency)}
      </Text>
      {(compareAt && (compareAt > price)) ? (
        <Text tag="del" size="lg" className="relative text-muted-foreground" data-testid="compare-at">
          <Inline className="sr-only">
            {was}
          </Inline>
          {fmtMoney(compareAt, currency)}
        </Text>
      ) : null}
      {badge ? (
        <Badge variant="default" size="default">
          {badge}
        </Badge>
      ) : null}
    </Group>
  );
}
